1424: {
1425: 	u8 ptype;
1426: 	u16 pdu_len;
1427: 	struct sk_buff *new_skb;
1428: 
1429: 	if (skb->len <= LLCP_HEADER_SIZE) {
1430: 		pr_err("Malformed AGF PDU\n");
1431: 		return;
1432: 	}
1433: 
1434: 	skb_pull(skb, LLCP_HEADER_SIZE);
1435: 
1436: 	while (skb->len > LLCP_AGF_PDU_HEADER_SIZE) {
1437: 		pdu_len = skb->data[0] << 8 | skb->data[1];
1438: 
1439: 		skb_pull(skb, LLCP_AGF_PDU_HEADER_SIZE);
1440: 
1441: 		if (pdu_len < LLCP_HEADER_SIZE || pdu_len > skb->len) {
1442: 			pr_err("Malformed AGF PDU\n");
1443: 			return;
1444: 		}
1445: 
1446: 		ptype = nfc_llcp_ptype(skb);
1447: 
1448: 		if (ptype == LLCP_PDU_SYMM || ptype == LLCP_PDU_AGF)
1449: 			goto next;
1450: 
1451: 		new_skb = nfc_alloc_recv_skb(pdu_len, GFP_KERNEL);
1452: 		if (new_skb == NULL) {
1453: 			pr_err("Could not allocate PDU\n");
1454: 			return;
1455: 		}
1456: 
1457: 		skb_put_data(new_skb, skb->data, pdu_len);
1458: 
1459: 		nfc_llcp_rx_skb(local, new_skb);
1460: 
1461: 		kfree_skb(new_skb);
1462: next:
1463: 		skb_pull(skb, pdu_len);
1464: 	}
